-- ---- Luxembourg: card 2, "Mandatory content" ----
UPDATE deep_dive_card_translations SET note = 'Public bodies can reject non-compliant e-invoices outright, so missing or mismatched fields — particularly the contract reference — are the most common cause of payment delay, not outright fines.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Luxembourg' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Los organismos públicos pueden rechazar directamente las facturas electrónicas no conformes, por lo que los campos ausentes o incorrectos — en particular la referencia del contrato — son la causa más común de retraso en el pago, no las multas directas.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Luxembourg' AND d.section = 'file_format' AND d.sort_order = 2);
