UPDATE deep_dive_card_translations SET note = 'El período de conservación de 10 años de Luxemburgo es más largo que en varios mercados vecinos — téngalo en cuenta en cualquier contrato con un Punto de Acceso Peppol, ya que necesitará acceso continuado a las facturas históricas mucho después de un posible cambio de proveedor.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Luxembourg' AND d.section = 'file_format' AND d.sort_order = 3);
