-- ---- South Korea: card 0, "Format & standard" ----
UPDATE deep_dive_card_translations SET note = 'The XML-plus-digital-signature pattern has been stable for over a decade, so most accounting and ERP systems already support it natively — the real integration decision is which of the five submission channels to use.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'South Korea' AND d.section = 'file_format' AND d.sort_order = 0);
