-- ---- South Korea: card 3, "Archiving" ----
UPDATE deep_dive_card_translations SET note = 'The government''s own centralized storage covering the retention requirement is a genuine convenience most newer mandates in this tracker don''t yet offer — one less thing for a compliant business to manage itself.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'South Korea' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Que el propio almacenamiento centralizado del gobierno cubra el requisito de conservación es una comodidad real que la mayoría de los mandatos más recientes de este seguimiento todavía no ofrecen — una cosa menos que gestionar para una empresa que cumple.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'South Korea' AND d.section = 'file_format' AND d.sort_order = 3);
