UPDATE deep_dive_card_translations SET note = 'Dix ans est une obligation de conservation plus longue que celle exigée par la plupart des pays de ce suivi — prévoyez une infrastructure d''archivage en conséquence, qu''elle soit interne ou confiée à un prestataire certifié (le stockage à l''étranger est autorisé sous certaines conditions de sécurité des données).' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Vietnam' AND d.section = 'file_format' AND d.sort_order = 3);

-- ---- Singapore: card 0, "Format & standard" ----
UPDATE deep_dive_card_translations SET note = 'Unlike clearance-model countries, InvoiceNow doesn''t require the taxpayer to digitally sign invoices — security, integrity, and authenticity are safeguarded by the Peppol network and accredited Access Point providers instead.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'A diferencia de los países con modelo de compensación, InvoiceNow no requiere que el contribuyente firme digitalmente las facturas — la seguridad, integridad y autenticidad están salvaguardadas por la red Peppol y los proveedores de Puntos de Acceso acreditados.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'Anders als in Ländern mit Clearing-Modell verlangt InvoiceNow keine digitale Signatur der Rechnungen durch den Steuerpflichtigen — Sicherheit, Integrität und Authentizität werden stattdessen durch das Peppol-Netzwerk und akkreditierte Access-Point-Anbieter gewährleistet.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'Contrairement aux pays à modèle de contrôle, InvoiceNow n''exige pas du contribuable qu''il signe numériquement les factures — la sécurité, l''intégrité et l''authenticité sont plutôt garanties par le réseau Peppol et les fournisseurs de points d''accès agréés.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 0);

-- ---- Singapore: card 2, "Mandatory content" ----
