UPDATE deep_dive_card_translations SET note = 'Die korrekte Zuordnung Ihrer internen Steuercodes zur standardisierten GST-Kategorieliste der IRAS ist einer der Schritte mit dem höchsten technischen Reibungspotenzial — machen Sie hier Fehler, werden Ihre Einreichungen markiert.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 2);
