UPDATE deep_dive_card_translations SET note = 'Wenn Ihre Rechnungsvorlagen vor der GST-Anforderung von InvoiceNow erstellt wurden, erwarten Sie erhebliche Lücken gegenüber den neueren PINT-SG-konformen Feldanforderungen — prüfen Sie dies, statt Kompatibilität anzunehmen.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Singapore' AND d.section = 'file_format' AND d.sort_order = 4);
