UPDATE deep_dive_card_translations SET note = 'Las fallas de validación en la LHDN se rechazan de forma cerrada — el documento se rechaza directamente en lugar de aceptarse con una advertencia, por lo que acertar con estos 55 campos desde el principio realmente importa.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Malaysia' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Validierungsfehler bei der LHDN schlagen fehlgeschlossen zu — das Dokument wird direkt abgelehnt statt mit einer Warnung akzeptiert, weshalb es wirklich darauf ankommt, diese 55 Felder gleich beim ersten Mal richtig zu haben.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Malaysia' AND d.section = 'file_format' AND d.sort_order = 2);
