-- ---- Poland: card 0, "Format & standard" ----
UPDATE deep_dive_card_translations SET note = 'FA(3) was shaped directly by tax consultations with entrepreneurs, accountants, auditors, and IT vendors — the attachment support in particular was a direct response to feedback that FA(2) was too rigid for real-world invoicing scenarios.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'FA(3) se configuró directamente mediante consultas fiscales con emprendedores, contables, auditores y proveedores de TI — el soporte de adjuntos en particular fue una respuesta directa a los comentarios de que FA(2) era demasiado rígido para escenarios de facturación reales.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'FA(3) wurde direkt durch steuerliche Konsultationen mit Unternehmern, Steuerberatern, Prüfern und IT-Anbietern geformt — die Anhang-Unterstützung war insbesondere eine direkte Reaktion auf Rückmeldungen, dass FA(2) für reale Rechnungsstellungsszenarien zu starr war.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'FA(3) a été façonné directement par des consultations fiscales avec entrepreneurs, comptables, auditeurs et fournisseurs informatiques — la prise en charge des pièces jointes en particulier a été une réponse directe aux retours indiquant que FA(2) était trop rigide pour des scénarios de facturation réels.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 0);

-- ---- Poland: card 2, "Mandatory content" ----
UPDATE deep_dive_card_translations SET note = 'Suppliers don''t apply their own qualified signature — KSeF''s own clearance process (validation, sealing, and reference number assignment) is what gives the invoice legal force, similar in spirit to Italy''s SDI model.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Los proveedores no aplican su propia firma cualificada — el propio proceso de compensación de KSeF (validación, sellado y asignación del número de referencia) es lo que otorga fuerza legal a la factura, de manera similar en espíritu al modelo SDI de Italia.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Lieferanten bringen keine eigene qualifizierte Signatur an — der eigene Clearing-Prozess von KSeF (Validierung, Versiegelung und Zuweisung der Referenznummer) verleiht der Rechnung Rechtskraft, ähnlich im Grundgedanken wie Italiens SDI-Modell.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Les fournisseurs n''apposent pas leur propre signature qualifiée — c''est le processus de contrôle propre à KSeF (validation, scellement et attribution du numéro de référence) qui confère force légale à la facture, dans un esprit similaire au modèle SDI italien.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 2);

-- ---- Poland: card 4, "Clearance output" ----
UPDATE deep_dive_card_translations SET note = 'An invoice without a valid KSeF number is not valid for tax purposes — this is the sharpest practical difference from decentralised models like Germany''s, where the file itself carries legal weight without a central clearance step.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Una factura sin un número KSeF válido no es válida a efectos fiscales — esta es la diferencia práctica más marcada respecto a modelos descentralizados como el de Alemania, donde el propio archivo tiene fuerza legal sin un paso de compensación central.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Eine Rechnung ohne gültige KSeF-Nummer ist steuerlich nicht gültig — dies ist der schärfste praktische Unterschied zu dezentralisierten Modellen wie dem Deutschlands, wo die Datei selbst ohne zentralen Clearing-Schritt Rechtskraft trägt.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Une facture sans numéro KSeF valide n''est pas valable à des fins fiscales — c''est la différence pratique la plus nette par rapport aux modèles décentralisés comme celui de l''Allemagne, où le fichier lui-même a force légale sans étape de contrôle central.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 4);

-- ---- Poland: card 3, "Archiving" ----
UPDATE deep_dive_card_translations SET note = 'Because KSeF stores every validated invoice centrally for 10 years, businesses don''t need to independently archive invoice XML files for compliance purposes — a genuine operational simplification compared to decentralised regimes.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Dado que KSeF almacena centralmente cada factura validada durante 10 años, las empresas no necesitan archivar de forma independiente los archivos XML de facturas para fines de cumplimiento — una simplificación operativa genuina en comparación con los regímenes descentralizados.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Da KSeF jede validierte Rechnung 10 Jahre zentral speichert, müssen Unternehmen Rechnungs-XML-Dateien für Compliance-Zwecke nicht eigenständig archivieren — eine echte betriebliche Vereinfachung im Vergleich zu dezentralisierten Regimen.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Comme KSeF stocke chaque facture validée de manière centrale pendant 10 ans, les entreprises n''ont pas besoin d''archiver indépendamment les fichiers XML de factures à des fins de conformité — une véritable simplification opérationnelle par rapport aux régimes décentralisés.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Poland' AND d.section = 'file_format' AND d.sort_order = 3);

-- ---- Romania: card 0, "Format & standard" ----
UPDATE deep_dive_card_translations SET note = 'CII XML is technically permitted by the EN 16931 standard, but UBL 2.1 is what ANAF''s platform actually validates in practice — use UBL unless you have a specific reason not to.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'El XML CII está técnicamente permitido por el estándar EN 16931, pero en la práctica la plataforma de la ANAF valida realmente UBL 2.1 — use UBL a menos que tenga una razón específica para no hacerlo.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'CII-XML ist gemäß dem EN-16931-Standard technisch zulässig, aber in der Praxis validiert die ANAF-Plattform tatsächlich UBL 2.1 — verwenden Sie UBL, sofern Sie keinen bestimmten Grund dagegen haben.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET note = 'Le XML CII est techniquement autorisé par la norme EN 16931, mais c''est UBL 2.1 que la plateforme de l''ANAF valide réellement en pratique — utilisez UBL sauf raison spécifique de ne pas le faire.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 0);

-- ---- Romania: card 4, "Validation pipeline" ----
UPDATE deep_dive_card_translations SET note = 'Invalid or inactive CUI/CIF tax IDs cause immediate rejection — the system cross-references ANAF''s live taxpayer database as part of validation, not just a formatting check.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Los NIF CUI/CIF no válidos o inactivos provocan un rechazo inmediato — el sistema cruza la información con la base de datos de contribuyentes en vivo de la ANAF como parte de la validación, no solo una comprobación de formato.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Ungültige oder inaktive CUI/CIF-Steuer-IDs führen zur sofortigen Ablehnung — das System gleicht als Teil der Validierung mit der Live-Steuerpflichtigendatenbank der ANAF ab, nicht nur mit einer Formatprüfung.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 4);
UPDATE deep_dive_card_translations SET note = 'Des numéros fiscaux CUI/CIF invalides ou inactifs entraînent un rejet immédiat — le système croise les données avec la base des contribuables en temps réel de l''ANAF dans le cadre de la validation, pas seulement un contrôle de format.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 4);

-- ---- Romania: card 2, "Mandatory content" ----
UPDATE deep_dive_card_translations SET note = 'Romanian-specific tax category codes are required for reverse-charge and simplified invoice scenarios — generic EN 16931 codes alone won''t pass Schematron validation.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Se requieren códigos de categoría fiscal específicos de Rumanía para los escenarios de inversión del sujeto pasivo y factura simplificada — los códigos genéricos de EN 16931 por sí solos no superarán la validación Schematron.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Für Reverse-Charge- und vereinfachte Rechnungsszenarien sind rumänienspezifische Steuerkategoriecodes erforderlich — allgemeine EN-16931-Codes allein bestehen die Schematron-Validierung nicht.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 2);
UPDATE deep_dive_card_translations SET note = 'Des codes de catégorie fiscale spécifiques à la Roumanie sont requis pour les scénarios d''autoliquidation et de facture simplifiée — les codes génériques EN 16931 seuls ne passeront pas la validation Schematron.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 2);

-- ---- Romania: card 3, "Archiving" ----
UPDATE deep_dive_card_translations SET note = 'Retain both the XML you submitted and ANAF''s signed response/downloadId — the government''s digital seal (not your own signature) is what makes the invoice legally valid.' WHERE lang = 'en' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Conserve tanto el XML que envió como la respuesta firmada/downloadId de la ANAF — el sello digital del gobierno (no su propia firma) es lo que hace que la factura sea legalmente válida.' WHERE lang = 'es' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Bewahren Sie sowohl das eingereichte XML als auch die signierte Antwort/downloadId der ANAF auf — das digitale Siegel des Staates (nicht Ihre eigene Signatur) macht die Rechnung rechtlich gültig.' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 3);
UPDATE deep_dive_card_translations SET note = 'Conservez à la fois le XML soumis et la réponse signée/downloadId de l''ANAF — c''est le sceau numérique de l''État (et non votre propre signature) qui rend la facture juridiquement valide.' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Romania' AND d.section = 'file_format' AND d.sort_order = 3);

